update public.about_settings set hero_alt_nl = (jsonb_populate_record(null::public.about_settings, '{"hero_alt_nl": "Twee mannen in MOSE hoodies"}'::jsonb)).hero_alt_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(hero_alt_nl), 'null'::jsonb) is not distinct from '"Irma en Rick (MOSE), oprichters, op de monumentale stenen trappen in Groningen"'::jsonb;
update public.about_settings set story_title_nl = (jsonb_populate_record(null::public.about_settings, '{"story_title_nl": "GOEDE KLEDING. ELKE DAG."}'::jsonb)).story_title_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(story_title_nl), 'null'::jsonb) is not distinct from '"ONS VERHAAL"'::jsonb;
update public.about_settings set story_paragraph1_nl = (jsonb_populate_record(null::public.about_settings, '{"story_paragraph1_nl": "MOSE maakt kleding voor mannen die houden van een stevige hoodie, een goed T-shirt en een broek die lekker zit. Duidelijke vormen, rustige kleuren en details die het verschil maken. Kleding die je makkelijk combineert en graag uit je kast pakt."}'::jsonb)).story_paragraph1_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(story_paragraph1_nl), 'null'::jsonb) is not distinct from '"Wij zijn Irma en Rick, de oprichters van MOSE.\n\nWe wonen met onze katten Bob en Marley en onze daggoe Guus in Groningen, in Helpman. Sinds september zijn we zelfs getrouwd. Wow, serieuze shit.\n\n“Waarom MOSE?” Onze overleden poes heette Mosie, we noemden haar Moos. Dit is ons eerbetoon. 🐱"'::jsonb;
update public.about_settings set story_paragraph2_nl = (jsonb_populate_record(null::public.about_settings, '{"story_paragraph2_nl": "Het begint bij hoe iets valt en aanvoelt. Een ruime pasvorm waar dat past, een stevige stof en een logo dat niet alle aandacht opeist. Van een eenvoudige Tee tot een boxy hoodie of barrel jeans: elk model heeft zijn eigen vorm en karakter."}'::jsonb)).story_paragraph2_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(story_paragraph2_nl), 'null'::jsonb) is not distinct from '"We zijn MOSE gestart omdat fast fashion ons irriteert. We kochten vaak dure t-shirts die na een paar keer wassen klaar waren voor de prullenbak. Daarom maken we kleding die blijft. Duurzaam, eerlijk en lokaal. Ook na tig keer wassen.\n\nLokaal? Ja. Gewoon gemaakt in het atelier in Groningen."'::jsonb;
update public.about_settings set local_title_nl = (jsonb_populate_record(null::public.about_settings, '{"local_title_nl": "GEEN POESPAS. WEL KARAKTER."}'::jsonb)).local_title_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(local_title_nl), 'null'::jsonb) is not distinct from '"LOKAAL GEMAAKT IN GRONINGEN"'::jsonb;
update public.about_settings set local_text_nl = (jsonb_populate_record(null::public.about_settings, '{"local_text_nl": "Voor ons zit een sterke outfit in de combinatie. Een goed shirt op je favoriete jeans. Een hoodie voor onderweg. Een sweater die je zo aantrekt. MOSE geeft je de basis; jij maakt er je eigen outfit van."}'::jsonb)).local_text_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(local_text_nl), 'null'::jsonb) is not distinct from '"Al onze producten worden lokaal gemaakt in Groningen. Niet omdat het hip is, maar omdat we precies willen weten waar onze kleding vandaan komt en hoe het gemaakt wordt. Eerlijk, transparant, en met respect voor iedereen die eraan werkt."'::jsonb;
