update public.about_settings set value_quality_title_nl = (jsonb_populate_record(null::public.about_settings, '{"value_quality_title_nl": "De stof"}'::jsonb)).value_quality_title_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(value_quality_title_nl), 'null'::jsonb) is not distinct from '"Premium kwaliteit"'::jsonb;
update public.about_settings set value_quality_text_nl = (jsonb_populate_record(null::public.about_settings, '{"value_quality_text_nl": "Hoe een stof aanvoelt en valt, bepaalt veel. Bij elk artikel vind je de samenstelling en de details van het materiaal."}'::jsonb)).value_quality_text_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(value_quality_text_nl), 'null'::jsonb) is not distinct from '"Alleen de beste materialen en perfecte afwerking. Kleding die jarenlang meegaat."'::jsonb;
