update public.about_settings set value_local_made_text_nl = (jsonb_populate_record(null::public.about_settings, '{"value_local_made_text_nl": "Van regular tot boxy en ruimvallend. We kiezen de vorm die bij het kledingstuk past. De maattabel helpt je kiezen."}'::jsonb)).value_local_made_text_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(value_local_made_text_nl), 'null'::jsonb) is not distinct from '"100% geproduceerd in Groningen. We kennen iedereen die aan je kleding werkt."'::jsonb;
