update public.about_settings set value_fair_pricing_text_nl = (jsonb_populate_record(null::public.about_settings, '{"value_fair_pricing_text_nl": "Rustige kleuren, subtiele logo’s en een verzorgde afwerking. Precies genoeg om het kledingstuk eigen te maken."}'::jsonb)).value_fair_pricing_text_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(value_fair_pricing_text_nl), 'null'::jsonb) is not distinct from '"Geen opgeblazen prijzen of fake sales. Gewoon eerlijk geprijsd voor wat je krijgt."'::jsonb;
