update public.about_settings set why_sustainable_text_nl = (jsonb_populate_record(null::public.about_settings, '{"why_sustainable_text_nl": "Kleding voor de dagen waarop je iets goeds aan wilt trekken zonder er lang over na te denken."}'::jsonb)).why_sustainable_text_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(why_sustainable_text_nl), 'null'::jsonb) is not distinct from '"We maken kleding die lang meegaat. Dat is de beste sustainability."'::jsonb;
