update public.about_settings set why_stylish_text_nl = (jsonb_populate_record(null::public.about_settings, '{"why_stylish_text_nl": "Hoodies, shirts, sweaters en broeken die samen werken, maar ook bij wat je al draagt."}'::jsonb)).why_stylish_text_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(why_stylish_text_nl), 'null'::jsonb) is not distinct from '"Basics met karakter. Voor moderne mannen en vrouwen die weten wat ze willen."'::jsonb;
