update public.about_settings set why_local_text_nl = (jsonb_populate_record(null::public.about_settings, '{"why_local_text_nl": "Stevige vormen en ingetogen details. Een stoere uitstraling, zonder dat het schreeuwerig wordt."}'::jsonb)).why_local_text_nl where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(why_local_text_nl), 'null'::jsonb) is not distinct from '"Gemaakt in Groningen, voor iedereen."'::jsonb;
