update public.about_settings set story_title_en = (jsonb_populate_record(null::public.about_settings, '{"story_title_en": "GOOD CLOTHES. EVERY DAY."}'::jsonb)).story_title_en where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(story_title_en), 'null'::jsonb) is not distinct from '"OUR STORY"'::jsonb;
update public.about_settings set story_paragraph1_en = (jsonb_populate_record(null::public.about_settings, '{"story_paragraph1_en": "MOSE makes clothes for men who appreciate a substantial hoodie, a good T-shirt and comfortable trousers. Clear shapes, understated colours and considered details. Clothes that are easy to combine and easy to reach for."}'::jsonb)).story_paragraph1_en where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(story_paragraph1_en), 'null'::jsonb) is not distinct from '"We''re Irma and Rick, the founders of MOSE.\n\nWe live with our cats Bob and Marley and our doggo Guus in Groningen, in Helpman. As of September we''re even married. Wow, serious stuff.\n\n\"Why MOSE?\" Our late cat was named Mosie, we called her Moos. This is our tribute to her. 🐱"'::jsonb;
update public.about_settings set story_paragraph2_en = (jsonb_populate_record(null::public.about_settings, '{"story_paragraph2_en": "It starts with the fit and feel. Room where you need it, a substantial fabric and a logo that does not demand attention. From a simple Tee to a boxy hoodie or barrel jeans, each style has its own shape and character."}'::jsonb)).story_paragraph2_en where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(story_paragraph2_en), 'null'::jsonb) is not distinct from '"We started MOSE because fast fashion irritates us. We kept buying expensive t-shirts that were ready for the bin after a few washes. So we make clothing that lasts. Sustainable, honest and local. Even after countless washes.\n\nLocal? Yes. Just made in the atelier in Groningen."'::jsonb;
update public.about_settings set local_title_en = (jsonb_populate_record(null::public.about_settings, '{"local_title_en": "NO NONSENSE. PURE CHARACTER."}'::jsonb)).local_title_en where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(local_title_en), 'null'::jsonb) is not distinct from '"LOCALLY MADE IN GRONINGEN"'::jsonb;
update public.about_settings set local_text_en = (jsonb_populate_record(null::public.about_settings, '{"local_text_en": "A good outfit comes down to how you put it together. A favourite shirt and jeans. A hoodie for heading out. A sweater you can pull on and go. MOSE gives you the foundation; you make it your own."}'::jsonb)).local_text_en where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(local_text_en), 'null'::jsonb) is not distinct from '"All our products are locally made in Groningen. Not because it''s trendy, but because we want to know exactly where our clothing comes from and how it''s made. Honest, transparent, and with respect for everyone involved in the process."'::jsonb;
