update public.about_settings set value_local_made_text_en = (jsonb_populate_record(null::public.about_settings, '{"value_local_made_text_en": "From regular to boxy and relaxed. The shape should suit the garment. Use the size chart to find your fit."}'::jsonb)).value_local_made_text_en where id = 'c53facaf-9faa-429f-bd51-20da3314c3fe' and coalesce(to_jsonb(value_local_made_text_en), 'null'::jsonb) is not distinct from '"100% produced in Groningen. We know everyone who works on your clothing."'::jsonb;
