update public.products set description = (jsonb_populate_record(null::public.products, '{"description": "**MOSE Classic Sweater. Comfort dat je voelt.**\n\nSommige sweaters hebben weinig nodig om goed te zijn. De Classic Sweater is gemaakt van katoenen joggingfleece van 300 gram per vierkante meter. De stevige stof heeft een zachte binnenkant en een OEKO-Tex-certificaat.\n\nDe regular fit biedt ruimte om te bewegen, terwijl de geribde manchetten en zoom zorgen voor een verzorgde afwerking. Geen onnodige details, wel aandacht voor wat telt.\n\nCombineer hem met je favoriete jeans of draag hem over een Tee.\n\n**Zacht vanbinnen. Sterk in eenvoud. Een sweater waar je graag naar teruggrijpt.**"}'::jsonb)).description where id = '7562c8b3-a7f7-457a-925e-145035b00feb' and coalesce(to_jsonb(description), 'null'::jsonb) is not distinct from '"**MOSE Classic Sweater. Comfort dat je voelt.**\n\nSommige sweaters hebben weinig nodig om goed te zijn. De Classic Sweater is gemaakt van katoenen joggingfleece van 300 gram per vierkante meter. De stevige stof heeft een zachte binnenkant en een OEKO-Tex-certificaat.\n\nDe regular fit biedt ruimte om te bewegen, terwijl de geribde manchetten en zoom zorgen voor een verzorgde afwerking. Geen onnodige details, wel aandacht voor wat telt.\n\nDe sweater wordt gemaakt in het atelier in Groningen.\n\n**Zacht vanbinnen. Sterk in eenvoud. Een sweater waar je graag naar teruggrijpt.**"'::jsonb;
update public.products set description_en = (jsonb_populate_record(null::public.products, '{"description_en": "**MOSE Classic Sweater. Comfort, with nothing to prove.**\n\nMade from 300 gsm cotton sweatshirt fleece, the Classic Sweater has a substantial feel and a soft inside. Its fabric carries an OEKO-Tex certificate.\n\nThe regular fit gives you room to move, while ribbed cuffs and hem keep the finish clean and simple.\n\nPair it with your favourite jeans or wear it over a Tee.\n\n**The kind of comfort you notice the moment you put it on. The kind of design that doesn''t ask for attention.**"}'::jsonb)).description_en where id = '7562c8b3-a7f7-457a-925e-145035b00feb' and coalesce(to_jsonb(description_en), 'null'::jsonb) is not distinct from '"**MOSE Classic Sweater. Comfort, with nothing to prove.**\n\nMade from 300 gsm cotton sweatshirt fleece, the Classic Sweater has a substantial feel and a soft inside. Its fabric carries an OEKO-Tex certificate.\n\nThe regular fit gives you room to move, while ribbed cuffs and hem keep the finish clean and simple.\n\nThe sweater is made at the atelier in Groningen, where the finishing is done by hand.\n\n**The kind of comfort you notice the moment you put it on. The kind of design that doesn''t ask for attention.**"'::jsonb;
update public.products set meta_description = (jsonb_populate_record(null::public.products, '{"meta_description": "Katoenen joggingfleece van 300 g/m², een zachte binnenkant en regular fit. Ontdek de MOSE Classic Sweater."}'::jsonb)).meta_description where id = '7562c8b3-a7f7-457a-925e-145035b00feb' and coalesce(to_jsonb(meta_description), 'null'::jsonb) is not distinct from '"Katoenen joggingfleece van 300 g/m², een zachte binnenkant en regular fit. Ontdek de MOSE Classic Sweater, gemaakt in Groningen."'::jsonb;
update public.products set meta_description_en = (jsonb_populate_record(null::public.products, '{"meta_description_en": "The MOSE Classic Sweater uses 300 gsm cotton sweatshirt fleece, with a soft interior, regular fit and ribbed cuffs."}'::jsonb)).meta_description_en where id = '7562c8b3-a7f7-457a-925e-145035b00feb' and coalesce(to_jsonb(meta_description_en), 'null'::jsonb) is not distinct from '"The MOSE Classic Sweater uses 300 gsm cotton sweatshirt fleece, with a soft interior, regular fit and ribbed cuffs. Made in Groningen."'::jsonb;
update public.products set description = (jsonb_populate_record(null::public.products, '{"description": "**MOSE Essential Hoodie. Comfort voor iedere dag.**\n\nEen hoodie moet goed zitten en prettig aanvoelen. De Essential Hoodie is gemaakt van katoenen joggingfleece van 300 gram per vierkante meter. De stof voelt stevig aan, met een zachte binnenkant en een OEKO-Tex-certificaat.\n\nDe regular fit geeft je ruimte om te bewegen. De capuchon en buikzak maken het ontwerp compleet, terwijl geribde manchetten en zoom zorgen voor een nette afwerking.\n\nDraag hem op denim of combineer hem met een ruimvallende broek.\n\n**Ontspannen in pasvorm. Verzorgd in uitstraling. Zonder gedoe.**"}'::jsonb)).description where id = '3692f227-52fc-41d5-911c-5c539448070b' and coalesce(to_jsonb(description), 'null'::jsonb) is not distinct from '"**MOSE Essential Hoodie. Comfort voor iedere dag.**\n\nEen hoodie moet goed zitten en prettig aanvoelen. De Essential Hoodie is gemaakt van katoenen joggingfleece van 300 gram per vierkante meter. De stof voelt stevig aan, met een zachte binnenkant en een OEKO-Tex-certificaat.\n\nDe regular fit geeft je ruimte om te bewegen. De capuchon en buikzak maken het ontwerp compleet, terwijl geribde manchetten en zoom zorgen voor een nette afwerking.\n\nDe hoodie wordt gemaakt in het atelier in Groningen, waar de afwerking met de hand gebeurt.\n\n**Ontspannen in pasvorm. Verzorgd in uitstraling. Zonder gedoe.**"'::jsonb;
update public.products set description_en = (jsonb_populate_record(null::public.products, '{"description_en": "**MOSE Essential Hoodie. Comfort you can count on.**\n\nThe Essential Hoodie is made from 300 gsm cotton sweatshirt fleece with a soft interior and an OEKO-Tex certificate. It''s substantial without needing to make a statement.\n\nA regular fit keeps things comfortable, with a hood, a front pouch pocket and ribbed cuffs and hem.\n\nWear it with denim or a pair of relaxed trousers.\n\n**Easy to wear, considered in the details. No extra noise, just the things a good hoodie should have.**"}'::jsonb)).description_en where id = '3692f227-52fc-41d5-911c-5c539448070b' and coalesce(to_jsonb(description_en), 'null'::jsonb) is not distinct from '"**MOSE Essential Hoodie. Comfort you can count on.**\n\nThe Essential Hoodie is made from 300 gsm cotton sweatshirt fleece with a soft interior and an OEKO-Tex certificate. It''s substantial without needing to make a statement.\n\nA regular fit keeps things comfortable, with a hood, a front pouch pocket and ribbed cuffs and hem.\n\nThe hoodie comes from the atelier in Groningen, where each one is finished by hand.\n\n**Easy to wear, considered in the details. No extra noise, just the things a good hoodie should have.**"'::jsonb;
