update public.products set meta_description_en = (jsonb_populate_record(null::public.products, '{"meta_description_en": "The MOSE Essential Hoodie features 300 gsm cotton sweatshirt fleece, a soft interior, regular fit, hood and front pouch pocket."}'::jsonb)).meta_description_en where id = '3692f227-52fc-41d5-911c-5c539448070b' and coalesce(to_jsonb(meta_description_en), 'null'::jsonb) is not distinct from '"The MOSE Essential Hoodie features 300 gsm cotton sweatshirt fleece, a soft interior, regular fit, hood and front pouch pocket. Made in Groningen."'::jsonb;
update public.products set description = (jsonb_populate_record(null::public.products, '{"description": "Even geen inspiratie voor (alweer) een cadeau? Met de MOSE Giftcard zit je altijd goed.\n\nLaat hem zelf kiezen uit de collectie. Van een goed T-shirt tot een comfortabele hoodie of zijn volgende favoriete broek."}'::jsonb)).description where id = 'bc6c495d-fbc9-48e4-8d24-a9f8f23e3b8c' and coalesce(to_jsonb(description), 'null'::jsonb) is not distinct from '"Even geen inspiratie voor (alweer) een cadeau? Met de MOSE Giftcard zit je altijd goed.\n\nLaat hem of haar zelf het favoriete piece kiezen uit de collectie. Premium basics, gemaakt in Groningen, gedragen met intentie."'::jsonb;
update public.products set description_en = (jsonb_populate_record(null::public.products, '{"description_en": "Out of gift ideas, again? The MOSE Gift Card never misses.\n\nLet him choose from the collection. From a good T-shirt to a comfortable hoodie or his next favourite pair of trousers."}'::jsonb)).description_en where id = 'bc6c495d-fbc9-48e4-8d24-a9f8f23e3b8c' and coalesce(to_jsonb(description_en), 'null'::jsonb) is not distinct from '"Out of gift ideas, again? The MOSE Gift Card never misses.\n\nLet them pick their own favourite from the collection. Premium basics, made in Groningen, worn with intention."'::jsonb;
update public.products set description = (jsonb_populate_record(null::public.products, '{"description": "**MOSE Tee. Jouw nieuwe everyday essential.**\n\nEen goed T-shirt begint bij de stof. Voor de MOSE Tee gebruiken we stevige jersey van 240 gram per vierkante meter. Hij voelt zacht aan, valt mooi en houdt zijn vorm, was na was.\n\nDankzij de regular fit sluit het shirt netjes aan zonder te knellen. Een geribde hals en verstevigde naden maken de afwerking compleet.\n\nDraag hem op zichzelf of als laag onder een hoodie of sweater.\n\n**Minimalistisch in ontwerp. Met aandacht gemaakt. Klaar voor iedere dag.**"}'::jsonb)).description where id = 'c5fa43eb-d196-4216-ac8d-67c34279b8c7' and coalesce(to_jsonb(description), 'null'::jsonb) is not distinct from '"**MOSE Tee. Jouw nieuwe everyday essential.**\n\nEen goed T-shirt begint bij de stof. Voor de MOSE Tee gebruiken we stevige jersey van 240 gram per vierkante meter. Hij voelt zacht aan, valt mooi en houdt zijn vorm, was na was.\n\nDankzij de regular fit sluit het shirt netjes aan zonder te knellen. Een geribde hals en verstevigde naden maken de afwerking compleet.\n\nDe stof heeft een OEKO-Tex-certificaat. De Tee wordt gemaakt in Groningen; het atelier daar werkt ieder exemplaar met de hand af.\n\n**Minimalistisch in ontwerp. Met aandacht gemaakt. Klaar voor iedere dag.**"'::jsonb;
update public.products set description_en = (jsonb_populate_record(null::public.products, '{"description_en": "**MOSE Tee. The everyday essential, done properly.**\n\nA good tee starts with its fabric. We use substantial 240 gsm jersey that feels soft, drapes neatly and keeps its shape, wash after wash.\n\nThe regular fit sits comfortably without feeling restrictive. A ribbed neck and reinforced seams give it a clean finish.\n\nWear it on its own or under a hoodie or sweater.\n\n**Nothing unnecessary in the design. Just a well-considered T-shirt you''ll want to wear again tomorrow.**"}'::jsonb)).description_en where id = 'c5fa43eb-d196-4216-ac8d-67c34279b8c7' and coalesce(to_jsonb(description_en), 'null'::jsonb) is not distinct from '"**MOSE Tee. The everyday essential, done properly.**\n\nA good tee starts with its fabric. We use substantial 240 gsm jersey that feels soft, drapes neatly and keeps its shape, wash after wash.\n\nThe regular fit sits comfortably without feeling restrictive. A ribbed neck and reinforced seams give it a clean finish.\n\nThe fabric carries an OEKO-Tex certificate. Production takes place at the atelier in Groningen, with the final finishing done by hand.\n\n**Nothing unnecessary in the design. Just a well-considered T-shirt you''ll want to wear again tomorrow.**"'::jsonb;
